/**
 * Names for the Slack mentions a message carries without a label. Slack
 * often sends `<#C…>` / `<#C…|>`, `<@U…>` and `<!subteam^S…>` bare, so the
 * name the person saw has to be looked up before the text reaches the model.
 * Lookups are cached per token, failures for a shorter time than names. A
 * failed or slow lookup is not waited for past a short budget and leaves the
 * mention to render as its id.
 */
import { callSlackApi } from "./api.js";
import { fetchSlackUserInfo, slackUserName } from "./user-info.js";
import { isRecord } from "../../internal/is-record.js";
export const SLACK_USER_MENTION_RE = /<@([A-Z0-9]+)(?:\|([^>]*))?>/g;
export const SLACK_CHANNEL_MENTION_RE = /<#([A-Z0-9]+)(?:\|([^>]*))?>/g;
export const SLACK_SUBTEAM_MENTION_RE = /<!subteam\^([A-Z0-9]+)(?:\|([^>]*))?>/g;
/** Distinct ids looked up per kind per call; the rest render as ids. */
const MAX_LOOKUPS_PER_KIND = 20;
const LOOKUP_CONCURRENCY = 4;
/** The turn waits at most this long; later answers still fill the cache. */
const LOOKUP_BUDGET_MS = 3_000;
function unlabeledIds(texts, pattern) {
    const ids = new Set();
    for (const text of texts) {
        for (const match of text.matchAll(pattern)) {
            const label = match[2]?.trim() ?? "";
            if (label === "" && ids.size < MAX_LOOKUPS_PER_KIND) {
                ids.add(match[1]);
            }
        }
    }
    return [...ids];
}
async function lookupInto(names, ids, lookup) {
    let next = 0;
    const worker = async () => {
        while (next < ids.length) {
            const id = ids[next++];
            const name = await lookup(id).catch(() => undefined);
            if (name !== undefined && name !== "") {
                names.set(id, name);
            }
        }
    };
    await Promise.all(Array.from({ length: Math.min(LOOKUP_CONCURRENCY, ids.length) }, worker));
}
/** A lookup that has not answered by then counts as failed, so its cache entry settles. */
const LOOKUP_TIMEOUT_MS = 10_000;
const FOUND_TTL_MS = 60 * 60_000;
/** Failed lookups (missing scope, unknown id, Slack down) are not retried before this. */
const FAILED_TTL_MS = 10 * 60_000;
const MAX_ENTRIES_PER_TOKEN = 1_000;
const channels = new Map();
const users = new Map();
const subteams = new Map();
export function resetSlackMentionNameCache() {
    channels.clear();
    users.clear();
    subteams.clear();
}
function settleWithin(pending) {
    let timer;
    const timeout = new Promise((resolve) => {
        timer = setTimeout(() => resolve(undefined), LOOKUP_TIMEOUT_MS);
        if (typeof timer === "object" && typeof timer.unref === "function") {
            timer.unref();
        }
    });
    return Promise.race([pending.catch(() => undefined), timeout]).finally(() => clearTimeout(timer));
}
function remembered(cache, botToken, key, fetch) {
    const perToken = cache.get(botToken) ?? new Map();
    cache.set(botToken, perToken);
    const hit = perToken.get(key);
    if (hit !== undefined && hit.expiresAt > Date.now()) {
        return hit.value;
    }
    perToken.delete(key);
    if (perToken.size >= MAX_ENTRIES_PER_TOKEN) {
        const oldest = perToken.keys().next();
        if (oldest.done !== true) {
            perToken.delete(oldest.value);
        }
    }
    const entry = {
        value: settleWithin(fetch()),
        expiresAt: Number.POSITIVE_INFINITY,
    };
    perToken.set(key, entry);
    void entry.value.then((value) => {
        entry.expiresAt = Date.now() + (value === undefined ? FAILED_TTL_MS : FOUND_TTL_MS);
    });
    return entry.value;
}
/**
 * Only public channel names are resolved. The bot can read private channels
 * it belongs to, but the people in the thread may not be members.
 */
async function fetchChannelName(botToken, channelId) {
    const result = await callSlackApi({
        botToken,
        operation: "conversations.info",
        body: { channel: channelId },
    });
    const channel = result.ok === true && isRecord(result.channel) ? result.channel : undefined;
    if (channel === undefined ||
        channel.is_private === true ||
        channel.is_im === true ||
        channel.is_mpim === true) {
        return undefined;
    }
    return typeof channel.name === "string" && channel.name !== "" ? channel.name : undefined;
}
function channelName(botToken, channelId) {
    return remembered(channels, botToken, channelId, () => fetchChannelName(botToken, channelId));
}
function userName(botToken, userId) {
    return remembered(users, botToken, userId, async () => {
        const user = await fetchSlackUserInfo({ botToken, userId });
        return user === undefined ? undefined : slackUserName(user);
    });
}
/** Slack has no `usergroups.info`, so one `usergroups.list` serves every id. */
async function fetchSubteamHandles(botToken) {
    const result = await callSlackApi({
        botToken,
        operation: "usergroups.list",
        body: {},
    });
    if (result.ok !== true || !Array.isArray(result.usergroups)) {
        return undefined;
    }
    const handles = new Map();
    for (const group of result.usergroups) {
        if (isRecord(group) && typeof group.id === "string" && typeof group.handle === "string") {
            handles.set(group.id, group.handle);
        }
    }
    return handles;
}
function subteamHandles(botToken) {
    return remembered(subteams, botToken, "", () => fetchSubteamHandles(botToken));
}
/**
 * Look up the unlabeled channel, user and user-group mentions in `texts`.
 * Never throws; with no token, or nothing to look up, it makes no call.
 */
export async function resolveSlackMentionNames(args) {
    const { botToken } = args;
    if (botToken === undefined) {
        return {};
    }
    const channelIds = unlabeledIds(args.texts, SLACK_CHANNEL_MENTION_RE);
    const userIds = unlabeledIds(args.texts, SLACK_USER_MENTION_RE);
    const subteamIds = unlabeledIds(args.texts, SLACK_SUBTEAM_MENTION_RE);
    if (channelIds.length + userIds.length + subteamIds.length === 0) {
        return {};
    }
    const channelNames = new Map();
    const userNames = new Map();
    const subteamNames = new Map();
    const work = Promise.all([
        lookupInto(channelNames, channelIds, (id) => channelName(botToken, id)),
        lookupInto(userNames, userIds, (id) => userName(botToken, id)),
        subteamIds.length === 0
            ? undefined
            : lookupInto(subteamNames, subteamIds, async (id) => (await subteamHandles(botToken))?.get(id)),
    ]);
    let timer;
    const budget = new Promise((resolve) => {
        timer = setTimeout(resolve, LOOKUP_BUDGET_MS);
    });
    await Promise.race([work, budget]);
    clearTimeout(timer);
    return {
        channels: new Map(channelNames),
        users: new Map(userNames),
        subteams: new Map(subteamNames),
    };
}
